function setLanguage(next){lang=next;storeSet('lahza-lang',lang);document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';$('#languageBtn').innerHTML=lang==='ar'?'EN <span class="language-circle">◎</span>':'عربي <span class="language-circle">◎</span>'; $$('[data-i18n]').forEach(el=>{const t=translations[lang][el.dataset.i18n]; if(t) el.innerHTML=t;else if(lang==='ar'&&el.dataset.arOriginal)el.innerHTML=el.dataset.arOriginal});renderHome();if(state.project)renderWorkspace();const search=$('#projectsSearch');if(search)search.placeholder=trans('بحث في التصاميم...','Search your designs...');if(state.project)refreshSelectionBar();}
