function bottleSvg(height=120){return `<svg viewBox="0 0 88 168" xmlns="http://www.w3.org/2000/svg" height="${height}"><defs><linearGradient id="btl" x1="0" x2="1"><stop stop-color="#aac2b7" stop-opacity=".72"/><stop offset=".21" stop-color="#fff" stop-opacity=".94"/><stop offset=".5" stop-color="#eaf5ef"/><stop offset=".83" stop-color="#c7d8d0"/><stop offset="1" stop-color="#819f92"/></linearGradient><linearGradient id="btlabel" x1="0" x2="1"><stop stop-color="#315b4e"/><stop offset=".3" stop-color="#527965"/><stop offset=".67" stop-color="#345e51"/><stop offset="1" stop-color="#1e4238"/></linearGradient></defs><path d="M32 31h24v7c0 6 8 11 13 15s8 9 8 15v81q0 15-14 15H25q-14 0-14-15V68q0-9 8-15c5-4 13-9 13-15z" fill="url(#btl)" stroke="#b6cbc0" stroke-width="1.2"/><rect x="29" y="5" width="30" height="29" rx="4" fill="#365a4d"/><path d="M30 9h28M30 15h28M30 21h28M30 27h28" stroke="#6f9680" stroke-width="1.2"/><path d="M13 82h62v47H13z" fill="url(#btlabel)"/><path d="M19 85v39m52-39v39" stroke="#d3e7da" opacity=".19" stroke-width="3"/><path d="m44 91 5 9-5 8-5-8z" fill="#ded0ae"/><path d="M32 112h24" stroke="#edeee1" stroke-width="1.5"/><path d="M27 116h34" stroke="#dbe3d3" opacity=".8" stroke-width="1"/><path d="M18 41v112" stroke="#fff" stroke-width="3" opacity=".7"/></svg>`}
