 return `<svg viewBox="0 0 160 160"><rect x="18" y="53" width="124" height="74" rx="13" fill="#d8ddd2"/><path d="M18 68q62-22 124 0v41q-62 18-124 0z" fill="#fafaf4" stroke="#c4cdc1"/><path d="M42 74h76v28H42z" fill="#e5ecde"/><path d="m80 79 5 9-5 9-5-9z" fill="#73937b"/><path d="M64 92h32" stroke="#99aa99"/></svg>`;
