function pdfDieline(x,y,f){const pts=[],n=96,half=f.theta/2,pt=(rho,a)=>[x+(f.width/2+rho*Math.sin(a))*PT,y+(f.trimH-(f.rho2-rho*Math.cos(a)))*PT];for(let i=0;i<=n;i++)pts.push(pt(f.rho2,-half+i*f.theta/n));for(let i=n;i>=0;i--)pts.push(pt(f.rho1,-half+i*f.theta/n));return '0.65 G 0.35 w\n'+pts.map((p,i)=>`${p[0].toFixed(3)} ${p[1].toFixed(3)} ${i?'l':'m'}`).join('\n')+'\nh S\n'}
function exportPdfBytes(){const layout=printLayout(),piece=layout.piece;if(!layout.perPage)throw Error(trans('التصميم أكبر من الورقة. يلزم ورق أكبر.','Artwork does not fit. Choose a bigger paper.'));let targetWidth=Math.min(3600,Math.max(700,Math.round(piece.w/25.4*300)));let canvas=pieceCanvas(targetWidth,true),jpeg=decodeDataUrl(canvas.toDataURL('image/jpeg',.95)),writer=new PDFWriter();const catalog=writer.reserve(),pagesNode=writer.reserve(),image=writer.add(writer.stream(`/Type /XObject /Subtype /Image /Width ${canvas.width} /Height ${canvas.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode`,jpeg)),pageIds=[];
 for(let pageNum=0;pageNum<layout.pages;pageNum++){const content=[];const count=Math.min(layout.perPage,layout.copies-pageNum*layout.perPage);for(let idx=0;idx<count;idx++){let col=idx%layout.cols,row=Math.floor(idx/layout.cols),xmm=layout.margin+col*(piece.w+layout.gap),ymm=layout.sheet.h-layout.margin-piece.h-row*(piece.h+layout.gap),x=xmm*PT,y=ymm*PT,w=piece.w*PT,h=piece.h*PT;content.push(`q\n${w.toFixed(5)} 0 0 ${h.toFixed(5)} ${x.toFixed(5)} ${y.toFixed(5)} cm\n/Im0 Do\nQ`);if(state.print.crop&&piece.wrap)content.push(pdfDieline(x,y,piece.wrap));else if(state.print.crop&&!layout.original)content.push(pdfCropMarks(x,y,w,h))}let bytes=encode.encode(content.join('\n')+'\n'),stream=writer.add(writer.stream('',bytes)),page=writer.add(`<< /Type /Page /Parent ${pagesNode} 0 R /MediaBox [0 0 ${(layout.sheet.w*PT).toFixed(5)} ${(layout.sheet.h*PT).toFixed(5)}] /Resources << /XObject << /Im0 ${image} 0 R >> >> /Contents ${stream} 0 R >>`);pageIds.push(page)}writer.set(pagesNode,`<< /Type /Pages /Count ${pageIds.length} /Kids [${pageIds.map(i=>`${i} 0 R`).join(' ')}] >>`);writer.set(catalog,`<< /Type /Catalog /Pages ${pagesNode} 0 R >>`);return writer.build(catalog)}
function qualityWarnings(){let problems=[],profile=currentProfile();for(const el of state.project.elements){if(el.type!=='image'||!el.originalWidth)continue;const printedW=el.w*profile.widthMm;const need=printedW/25.4*300;if(el.originalWidth<need*.8)problems.push(trans(`إحدى صورك أقل من 300 DPI تقريبًا عند هذا الحجم (${el.originalWidth} بكسل عرضًا).`,'One image may print below 300 DPI at this size.'))}return [...new Set(problems)]}
function printModalHtml(){const p=currentProfile(),layout=printLayout(),piece=layout.piece,warns=qualityWarnings(),status=getPrintReadiness();return `<div class="modal-kicker">${trans('الخطوة الأخيرة','FINAL STEP')}</div><h2>${trans('تجهيز ملف الطباعة','Prepare print file')}</h2><p class="modal-sub">${trans('التصميم المسطح فقط، بدون صورة المنتج أو علامات الواجهة.','Flat artwork only — no product mockup or editing controls.')}</p><div class="print-section"><h3>${trans('طريقة الطباعة','Choose print format')}</h3><div class="print-mode-row"><button class="print-mode ${state.print.mode==='original'?'selected':''}" data-print-mode="original"><strong>${trans('المقاس الأصلي','Original size')}</strong><small>${Math.round(piece.w*10)/10} × ${Math.round(piece.h*10)/10} mm</small></button><button class="print-mode ${state.print.mode==='sheet'?'selected':''}" data-print-mode="sheet"><strong>${trans('توزيع على ورقة','Multiple copies per sheet')}</strong><small>A4 / A3 / SRA3</small></button></div></div>${state.print.mode==='sheet'?`<div class="print-section"><div class="print-row"><label class="print-label">${trans('حجم الورق','Paper size')}<select data-print-paper><option value="A4" ${state.print.paper==='A4'?'selected':''}>A4 — 210 × 297 mm</option><option value="A3" ${state.print.paper==='A3'?'selected':''}>A3 — 297 × 420 mm</option><option value="SRA3" ${state.print.paper==='SRA3'?'selected':''}>SRA3 — 320 × 450 mm</option></select></label><label class="print-label">${trans('عدد النسخ','Copies')}<input type="number" data-print-copies min="1" max="300" value="${state.print.copies}"></label></div><label class="small-explain" style="display:flex;align-items:center;gap:8px;margin-top:11px"><input type="checkbox" data-print-crop ${state.print.crop?'checked':''}/> ${piece.wrap?trans('إضافة خط القص المقوّس','Include the curved cut line'):trans('إضافة خطوط قص','Include cut marks')}</label></div>`:''}${piece.wrap&&state.print.mode!=='sheet'?`<label class="small-explain" style="display:flex;align-items:center;gap:8px;margin-top:11px"><input type="checkbox" data-print-crop ${state.print.crop?'checked':''}/> ${trans('إضافة خط القص المقوّس','Include the curved cut line')}</label>`:''}${piece.wrap?`<p class="cup-template-note">ⓘ ${trans('غلاف الكوب ينطبع مقوّس مثل قالب المطبعة، عشان يلتف على الكوب المخروطي بدون ميلان.','Cup wraps print as a curved template so they sit level on a tapered cup.')}</p>`:''}<div class="print-preview" id="printPreview">${printPreviewHtml(layout)}</div><div class="print-stats" id="printStats">${printStatsHtml(layout)}</div><div class="readiness-box"><div class="readiness-title"><strong>${trans('مراجعة ما قبل الطباعة','Pre-print checklist')}</strong><span>${status.items.filter(i=>i.ok).length} / ${status.items.length}</span></div>${status.items.map(i=>`<div class="readiness-item"><span class="${i.ok?'ready':'needs-attention'}">${i.ok?'✓':'!'}</span><span>${i.text}</span></div>`).join('')}</div><div class="modal-note">ⓘ ${trans('الطباعة بالحجم الفعلي 100% بدون ملاءمة للصفحة، مع تجربة عينة على المنتج الحقيقي.','Print at Actual size (100%), not Fit to Page, and test on your physical product.')}</div>${warns.length?`<div class="modal-note" style="color:#a05a3c">⚠ ${warns.join('<br>')}</div>`:''}<p class="small-explain">${trans('الألوان RGB، وليست CMYK معتمدًا للمطابع الاحترافية.','RGB colors; not a CMYK press-ready profile.')}</p><div class="modal-bottom"><button class="button button-outline" id="printMockup">${trans('موكاب PNG','Mockup PNG')}</button><button class="button button-outline" id="downloadArtworkBtn">${trans('التصميم PNG','Artwork PNG')}</button><button class="button button-ghost" id="sharePdfBtn">${trans('مشاركة PDF','Share PDF')}</button><button class="button button-primary" id="downloadPdfBtn" ${!layout.perPage?'disabled':''}>↓ ${trans('تحميل PDF للطباعة','Download print PDF')}</button></div>`}
function printPreviewHtml(l){let ratio=l.sheet.w/l.sheet.h,maxH=170,maxW=310,w=Math.min(maxW,maxH*ratio),h=w/ratio;if(h>maxH){h=maxH;w=h*ratio}let tiles='';if(l.perPage){const cols=Math.min(l.cols,14),rows=Math.min(l.rows,16),count=Math.min(l.copies,cols*rows);const thumb=pieceCanvas(450).toDataURL('image/png');tiles=`<div class="sheet-tiles" style="grid-template-columns:repeat(${cols},1fr);grid-template-rows:repeat(${rows},1fr);gap:3px">${Array.from({length:count}).map(()=>`<div class="sheet-tile" style="background-image:url('${thumb}');background-size:100% 100%;background-repeat:no-repeat"></div>`).join('')}</div>`}return `<div class="print-sheet" style="width:${w}px;height:${h}px;max-width:100%">${tiles}</div>`}
function printStatsHtml(l){return `<span>${l.sheet.w} × ${l.sheet.h} mm</span><span>${l.perPage?trans(`${l.perPage} نسخة / ورقة • ${l.pages} صفحة`,`Up to ${l.perPage} copies / page · ${l.pages} page(s)`):trans('هذا المقاس لا يتسع على الورقة','Does not fit on this paper')}</span>`}
function showPrintModal(){if(!state.project)return;state.modal='print';state.print={mode:'original',paper:'A4',copies:1,crop:false};openModal(printModalHtml())}
function updatePrintModal(){if(state.modal!=='print')return;$('#modalContent').innerHTML=printModalHtml()}
async function downloadPdf(){try{await waitForArtworkImages();const bytes=exportPdfBytes();downloadBlob(new Blob([bytes],{type:'application/pdf'}),`Lahza-${state.project.title.replace(/[^\p{L}\p{N}-]+/gu,'-').slice(0,38)}-${state.print.mode==='original'?'Original':state.print.paper}.pdf`);toast(trans('تم تجهيز PDF بالمقاسات الصحيحة ✓','PDF generated with exact page dimensions ✓'))}catch(err){console.error(err);toast(err.message||trans('تعذّر تصدير PDF','PDF export failed'),true)}}

