 $('#modalContent').addEventListener('change',event=>{const el=event.target;if(el.matches('[data-wizard-custom]'))wizard.custom=el.checked;if(el.matches('[data-clone-size]'))cloneWizard.selected[el.dataset.cloneSize]=el.value;if(el.matches('[data-print-paper]')){state.print.paper=el.value;updatePrintModal()}if(el.matches('[data-print-crop]'))state.print.crop=el.checked;if(el.matches('[data-print-copies]')){state.print.copies=clamp(Number(el.value)||1,1,300);updatePrintModal()}});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();closeProps()}if(!state.project||$('#workspace').hidden||e.target.closest('input,textarea,select'))return;if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();removeElement()}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='z'){e.preventDefault();if(e.shiftKey)redo();else undo()}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='y'){e.preventDefault();redo()}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='d'){e.preventDefault();duplicateElement()}if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){const el=getSelected();if(el&&!el.locked&&!el.hidden){e.preventDefault();commitUndo();const step=e.shiftKey?.02:.002;const dir=document.documentElement.dir==='rtl'?-1:1;const r=getElementRect(el);if(e.key==='ArrowLeft')el.x=clamp(el.x-step*dir,r.w/2,1-r.w/2);if(e.key==='ArrowRight')el.x=clamp(el.x+step*dir,r.w/2,1-r.w/2);if(e.key==='ArrowUp')el.y=clamp(el.y-step,r.h/2,1-r.h/2);if(e.key==='ArrowDown')el.y=clamp(el.y+step,r.h/2,1-r.h/2);refreshPreview();saveSoon()}}});
