async function waitForArtworkImages(){if(!state.project)return;const urls=[...new Set(state.project.elements.filter(x=>x.type==='image'&&!x.hidden).map(x=>x.src))];await Promise.all(urls.map(async src=>{if(imageCache.get(src)?.ready)return;await new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>{imageCache.set(src,{img:im,ready:true});resolve()};im.onerror=()=>reject(new Error(trans('تعذر قراءة إحدى الصور','One image could not be loaded')));im.src=src})}))}


/* Mobile-first controls. Contextual actions never cover the artwork. */
function refreshSelectionBar(){
 const box=$('#selectionQuickbar');if(!box)return;
 const item=getSelected();box.hidden=!item||!!item.hidden||$('#workspace').hidden;
 if(!item||item.hidden)return;
 const title=item.type==='text'?(item.text||trans('نص','Text')):item.type==='image'?trans('صورة محددة','Selected photo'):trans('رمز محدد','Selected shape');
 $('#selectedItemLabel').textContent=String(title).slice(0,26);$('#editSelectedBtn').textContent=trans('✎ تعديل','✎ Edit');$('#duplicateSelectedBtn').textContent=trans('⧉ نسخ','⧉ Copy');$('#deleteSelectedBtn').setAttribute('aria-label',trans('حذف العنصر','Delete element'));
}
function toggleFocusMode(force){
 if(!state.project)return;
 const target=typeof force==='boolean'?force:!$('#workspace').classList.contains('focus-mode');
 $('#workspace').classList.toggle('focus-mode',target);
 $('#focusModeBtn').setAttribute('aria-pressed',String(target));
 $('#focusModeBtn').innerHTML=target?`⤡ <span>${trans('تصغير','Exit focus')}</span>`:`⛶ <span>${trans('تكبير','Focus view')}</span>`;
 closeProps();
 requestAnimationFrame(()=>{state.bottle?.draw();drawFlatEditor()});
}

/* Studio v2: physical sizes, production audit, guides and discoverable shortcuts. */
function refreshGuideControls(){document.querySelectorAll('[data-guide]').forEach(btn=>{const active=!!state.guides[btn.dataset.guide];btn.classList.toggle('active',active);btn.setAttribute('aria-pressed',String(active))})}
function showSizeModal(){if(!state.project)return;const p=currentProfile();if(p.wrap){state.modal='size';openModal(`<div class="modal-kicker">${trans('مقاس الطباعة','PRINT DIMENSIONS')}</div><h2>${trans('مقاس الكوب يجي من قالبه','The cup size comes from its template')}</h2><p class="modal-sub">${trans(`فوهة ${p.wrap.r1*2} مم، قاعدة ${p.wrap.r2*2} مم، ارتفاع ${p.wrap.h} مم. هذا قالب تجريبي، ولما يتوفر قالب المطبعة الحقيقي يتغيّر هنا.`,`Rim ${p.wrap.r1*2} mm, base ${p.wrap.r2*2} mm, height ${p.wrap.h} mm. A sample template until the printer's real one is added.`)}</p>`);return}state.modal='size';openModal(`<div class="modal-kicker">${trans('مقاس الطباعة','PRINT DIMENSIONS')}</div><h2>${trans('ضبط قياس الملصق','Set your label size')}</h2><p class="modal-sub">${trans('العرض والارتفاع الفعليين بالمليمتر. أي تغيير هنا يغيّر حجم الصفحة في PDF ولا يعني أن المقاس معتمد من الشركة المصنّعة.','Enter physical width and height in millimeters. This changes PDF page size but does not certify the dimensions.')}</p><div class="custom-size-grid"><label>${trans('العرض بالمليمتر','Width in millimeters')}<input id="sizeWidthInput" type="number" min="20" max="600" step="0.1" value="${p.widthMm}"></label><label>${trans('الارتفاع بالمليمتر','Height in millimeters')}<input id="sizeHeightInput" type="number" min="10" max="350" step="0.1" value="${p.heightMm}"></label></div><div class="dimension-examples"><span>1 cm = 10 mm</span><span>${trans('بمسطرة أو بقالب المطبعة','Use a ruler or the printer’s dieline')}</span></div><div class="modal-note">ⓘ ${trans('نوصي بهامش أمان 3 مم من داخل الأطراف. خطوط الأدلة تظهر في المحرر فقط ولا تدخل في ملف الطباعة.','Allow a 3 mm safe margin. Canvas guides are not exported into your print file.')}</div><div class="modal-bottom"><button class="button button-outline" id="resetSizeBtn">${trans('العودة للمقاس التجريبي','Reset to sample')}</button><button class="button button-primary" id="saveSizeBtn">${trans('اعتماد المقاس','Use this size')}</button></div>`)}
function applyCustomSize(){const widthMm=Number($('#sizeWidthInput')?.value),heightMm=Number($('#sizeHeightInput')?.value);if(!Number.isFinite(widthMm)||!Number.isFinite(heightMm)||widthMm<20||widthMm>600||heightMm<10||heightMm>350){toast(trans('العرض 20–600 مم، والارتفاع 10–350 مم.','Width 20–600 mm, height 10–350 mm.'),true);return}commitUndo();state.project.customSize={widthMm:Math.round(widthMm*10)/10,heightMm:Math.round(heightMm*10)/10};closeModal();renderWorkspace();refreshPreview();saveSoon();toast(trans('تم تحديث المقاس. يُنصح بعينة مطبوعة قبل الإنتاج.','Size updated. Print a test sample before production.'))}
function getPrintReadiness(){const project=state.project,profile=currentProfile(),quality=qualityWarnings(),hasContent=project.elements.some(el=>!el.hidden),items=[{ok:!!profile.custom,text:profile.custom?trans('المقاس المدخل مستخدم في ملف PDF (يحتاج تجربة فعلية)','Your dimensions will be used in PDF (test on the product)'):trans('المقاسات الافتراضية تجريبية — المقاس يُضبط من المحرر','Preset sizes are sample only — enter your real size')},{ok:hasContent,text:hasContent?trans('التصميم يحتوي عناصر للطباعة','Your artwork contains printable elements'):trans('التصميم فارغ — يحتاج نصًا أو صورة','Your artwork is empty — add text or images')},{ok:quality.length===0,text:quality.length?trans('بعض الصور قد تكون منخفضة الدقة عند الطباعة','Some photos may be low-resolution in print'):trans('لا يوجد تحذير دقة معروف للصور','No detected photo resolution warnings')},{ok:true,text:trans('الأدلة وخطوط اختيار العناصر لن تظهر في PDF','Editor guides and selection handles are excluded from PDF')}];return{items,quality}}
async function downloadArtwork(){if(!state.project)return;await waitForArtworkImages();const profile=currentProfile(),w=Math.max(800,Math.min(3600,Math.round(profile.widthMm/25.4*300))),canvas=renderExportCanvas(w);canvas.toBlob(blob=>{if(blob){downloadBlob(blob,`Lahza-${state.project.title.replace(/[^\p{L}\p{N}-]+/gu,'-').slice(0,45)}-Artwork.png`);toast(trans('تم تنزيل التصميم المسطح','Flat artwork downloaded'))}},'image/png')}
async function sharePdf(){if(!state.project)return;try{await waitForArtworkImages();const blob=new Blob([exportPdfBytes()],{type:'application/pdf'});const f=new File([blob],`Lahza-${state.project.title.slice(0,40)}.pdf`,{type:'application/pdf'});if(navigator.share&&navigator.canShare?.({files:[f]})){await navigator.share({files:[f],title:state.project.title})}else{downloadBlob(blob,f.name);toast(trans('المشاركة المباشرة غير مدعومة؛ تم تنزيل PDF بدلًا منها','Direct sharing unsupported — downloaded the PDF instead'))}}catch(err){if(err.name!=='AbortError')toast(trans('تعذرت المشاركة، والتنزيل متاح بدلها','Sharing failed; try downloading instead'),true)}}

const cloneWizard={selected:{}};
function profileFor(project){const list=profiles[project.productId]||profiles.water,base=list.find(p=>p.id===project.profileId)||list[0],c=project.customSize;return !base.wrap&&c&&Number.isFinite(c.widthMm)&&Number.isFinite(c.heightMm)&&c.widthMm>=20&&c.heightMm>=10?{...base,widthMm:c.widthMm,heightMm:c.heightMm,custom:true}:base}
function measureTextMm(el,heightMm){const ctx=document.createElement('canvas').getContext('2d'),px=100;ctx.font=`${el.font==='latin'?'600':'700'} ${px}px ${el.font==='latin'?"'DM Sans',Arial,sans-serif":"'IBM Plex Sans Arabic',Tahoma,sans-serif"}`;const lines=String(el.text||'').split(/\r?\n/).slice(0,8),sizeMm=(el.size||.2)*heightMm;return{w:Math.max(1,...lines.map(l=>ctx.measureText(l).width))/px*sizeMm,h:sizeMm*1.25*lines.length}}
/* Adapting to another product: every element keeps its centre. First the whole design scales evenly so it fits the new size
   (the smaller of the width and height ratios). Then all elements grow together, up to the larger ratio, while each stays
   inside the product and no two elements overlap that did not overlap before. Full-size background photos keep filling. */
function adaptElements(elements,from,to){const W1=from.widthMm,H1=from.heightMm,W2=to.widthMm,H2=to.heightMm,hr=H2/H1,wr=W2/W1,base=Math.min(hr,wr),top=Math.max(hr,wr)/base;
 const items=elements.map(e=>{const full=e.type!=='text'&&(e.w||0)>=.98&&(e.h||0)>=.98;let wmm,hmm;if(e.type==='text'){const m=measureTextMm(e,H1);wmm=m.w;hmm=m.h}else{wmm=(e.w||.1)*W1;hmm=(e.h||.3)*H1}return{e,full,skip:full||e.hidden,wmm,hmm}});
 const box=(it,W,H,s)=>({x0:it.e.x-it.wmm*s/W/2,x1:it.e.x+it.wmm*s/W/2,y0:it.e.y-it.hmm*s/H/2,y1:it.e.y+it.hmm*s/H/2});
 const hit=(a,b)=>a.x0<b.x1&&b.x0<a.x1&&a.y0<b.y1&&b.y0<a.y1;const live=items.filter(it=>!it.skip);
 const before=live.map(a=>live.map(b=>a!==b&&hit(box(a,W1,H1,1),box(b,W1,H1,1))));
 const fits=g=>{const bs=live.map(it=>box(it,W2,H2,base*g));for(let i=0;i<bs.length;i++){const b=bs[i];if(b.x0<.02||b.x1>.98||b.y0<.02||b.y1>.98)return false;for(let j=i+1;j<bs.length;j++)if(!before[i][j]&&hit(b,bs[j]))return false}return true};
 let grow=1;if(fits(top))grow=top;else if(fits(1)){let lo=1,hi=top;for(let k=0;k<24;k++){const mid=(lo+hi)/2;if(fits(mid))lo=mid;else hi=mid}grow=lo}
 const s=base*grow;
 return items.map(it=>{const el={...it.e,id:uid()};if(it.full){el.x=.5;el.y=.5;el.w=1;el.h=1;return el}const wN=it.wmm*s/W2,hN=it.hmm*s/H2;if(el.type==='text')el.size=(el.size||.2)*H1*s/H2;else{el.w=wN;el.h=hN}el.x=wN<1?clamp(el.x,wN/2,1-wN/2):.5;el.y=hN<1?clamp(el.y,hN/2,1-hN/2):.5;return el})}
function adaptProject(source,productId,profileId){const from=profileFor(source),p=JSON.parse(JSON.stringify(source)),product=productCatalog.find(x=>x.id===productId);p.id=uid();p.productId=productId;p.profileId=profileId;p.brandId='generic';p.customSize=null;p.elements=adaptElements(source.elements,from,profileFor(p));p.themeId=source.themeId||source.id;p.themeName=source.themeName||source.title;p.title=`${p.themeName} - ${trans(product?.ar||'نسخة',product?.en||'Copy')}`.slice(0,55);p.createdAt=Date.now();p.updatedAt=p.createdAt;return p}
function designsCount(n){return lang==='ar'?(n===1?'تصميم واحد':n===2?'تصميمين':n<=10?`${n} تصاميم`:`${n} تصميمًا`):`${n} design${n===1?'':'s'}`}
function openCloneModal(){cloneWizard.selected={};showCloneModal()}
function showCloneModal(){if(!state.project)return;state.modal='clone';const sel=cloneWizard.selected,ids=Object.keys(sel),cur=state.project.productId;openModal(`<div class="modal-kicker">${trans('ثيم واحد لمنتجات أكثر','ONE THEME, MORE PRODUCTS')}</div><h2>${trans('نسخ التصميم لمنتجات أخرى','Copy your design to more products')}</h2><p class="modal-sub">${trans('منتج واحد أو أكثر. كل منتج ينحفظ تصميم مستقل بنفس الصور والنصوص والألوان، والعناصر تتكيّف مع مقاسه. تصميمك الحالي ما يتغيّر.','Pick one or more products. Each becomes its own design with the same photos, text and colors, resized to fit. Your current design stays as it is.')}</p><div class="modal-label">${trans('المنتجات','Products')}</div><div class="clone-products multi">${productCatalog.map(x=>`<button class="clone-product ${sel[x.id]?'selected':''}" data-clone-toggle="${x.id}" aria-pressed="${!!sel[x.id]}"><span class="clone-tick">${sel[x.id]?'✓':''}</span>${productSvg(x.id)}<strong>${trans(x.ar,x.en)}</strong>${x.id===cur?`<small>${trans('بمقاس ثاني','Another size')}</small>`:''}</button>`).join('')}</div>${ids.length?`<div class="modal-label">${trans('مقاس كل منتج','Size for each product')}</div><div class="clone-plan">${ids.map(id=>{const pr=productCatalog.find(x=>x.id===id);return `<div class="clone-row"><strong>${trans(pr.ar,pr.en)}</strong><select data-clone-size="${id}" aria-label="${trans('المقاس','Size')}">${profiles[id].map(o=>`<option value="${o.id}" ${sel[id]===o.id?'selected':''}>${trans(o.ar,o.en)} — ${o.widthMm} × ${o.heightMm} mm</option>`).join('')}</select></div>`}).join('')}</div>`:''}<div class="modal-note">ⓘ ${trans('المقاسات تجريبية. إذا اختلف شكل المنتج كثير (مثل قارورة إلى ستيكر دائري)، تستاهل مراجعة ترتيب العناصر قبل الطباعة.','Preset sizes are samples. When the shape changes a lot (bottle to round sticker), review the layout before printing.')}</div><div class="modal-bottom"><button class="button button-outline" onclick="document.getElementById('closeModal').click()">${trans('إلغاء','Cancel')}</button><button class="button button-primary" id="finishClone" ${ids.length?'':'disabled'}>${ids.length?`${trans('إنشاء','Create')} ${designsCount(ids.length)}`:trans('اختيار منتج','Pick a product')}</button></div>`)}
async function finishClone(){const old=state.project;if(!old)return;const picks=Object.entries(cloneWizard.selected);if(!picks.length)return;old.themeId=old.themeId||old.id;old.themeName=old.themeName||old.title;await saveNow(false);const made=[];for(const [productId,profileId] of picks){const p=adaptProject(old,productId,profileId);try{await dbPut(p);made.push(p)}catch(err){console.error(err)}}if(!made.length){toast(trans('ما قدرنا نحفظ النسخ على هذا الجهاز.','Could not save the copies on this device.'),true);return}state.modal='clone-done';openModal(`<div class="modal-kicker">${trans('تم','DONE')}</div><h2>${trans(`جهّزنا ${designsCount(made.length)} بنفس الثيم`,`${designsCount(made.length)} ready with the same theme`)}</h2><p class="modal-sub">${trans('كلها محفوظة في «تصاميمي». أي واحد منها يفتح ويتعدّل براحة.','All saved in My designs. Open any of them to adjust.')}</p><div class="clone-result">${made.map(p=>`<div class="clone-result-item"><span>${htmlEscape(p.title)} · ${(()=>{const o=profileFor(p);return `${o.widthMm} × ${o.heightMm} mm`})()}</span><button class="button button-primary button-sm" data-open-project="${p.id}">${trans('فتح','Open')}</button></div>`).join('')}</div><div class="modal-bottom"><button class="button button-outline" onclick="document.getElementById('closeModal').click()">${trans('أكمل على التصميم الحالي','Keep editing this design')}</button></div>`)}

function helpModalHtml(){return `<div class="modal-kicker">${trans('دليل استوديو لحظة','LAHZA STUDIO GUIDE')}</div><h2>${trans('تصميم بثقة','Design with confidence')}</h2><div class="help-list"><div><b>01</b><span><strong>${trans('إضافة العناصر','Add your artwork')}</strong><small>${trans('أكثر من صورة، ونصوص وأشكال.','Upload several photos and add text or shapes.')}</small></span></div><div><b>02</b><span><strong>${trans('تحريك بحرية','Arrange visually')}</strong><small>${trans('السحب على التصميم المسطح، أو على القارورة والكوب في وضع 3D.','Drag items on the flat canvas, or on the bottle or cup in 3D.')}</small></span></div><div><b>03</b><span><strong>${trans('مراجعة القياس والدقة','Check size and quality')}</strong><small>${trans('الأبعاد بالمليمتر؛ الخط البرتقالي المتقطع هو هامش أمان 3 مم.','Set your real dimensions in mm; orange dashed line is a 3 mm safety guide.')}</small></span></div><div><b>04</b><span><strong>${trans('التحميل والطباعة','Export and print')}</strong><small>${trans('PDF بالمقاس الأصلي أو توزيع نسخ على ورق، والطباعة بنسبة 100%.','Export actual-size PDF or sheet layouts, and print at 100%.')}</small></span></div></div><div class="shortcut-help"><strong>${trans('اختصارات الكمبيوتر','Keyboard shortcuts')}</strong><div><span>Ctrl / ⌘ + Z</span><span>${trans('تراجع','Undo')}</span></div><div><span>Ctrl / ⌘ + D</span><span>${trans('نسخ العنصر','Duplicate')}</span></div><div><span>↑ ↓ ← →</span><span>${trans('تحريك دقيق','Fine movement')}</span></div><div><span>Shift + ↑ ↓</span><span>${trans('تحريك أسرع','Move faster')}</span></div></div><div class="modal-note">${trans('المشروع يُحفظ على جهازك فقط. نسخة JSON الاحتياطية متاحة من تصاميمي.','Projects are stored only on this device. Export a JSON backup from My Designs.')}</div>`}

function setupHero(){const canvas=$('#heroBottleCanvas');if(window.matchMedia('(max-width:680px)').matches){canvas.closest('.hero-showcase').classList.add('no-webgl');return}try{state.heroBottle=new Bottle3D(canvas,true);if(state.heroBottle.failed){canvas.closest('.hero-showcase').classList.add('no-webgl');return;}const sample=createProject('water','medium','generic','graduation');sample.elements.find(x=>x.type==='text').text='مبروك يا نورة';const c=document.createElement('canvas');c.width=1200;c.height=316;drawScene(c.getContext('2d'),1200,316,sample);state.heroBottle.setArtwork(c);state.heroBottle.angle=-.3;state.heroBottle.zoom=1.03;state.heroBottle.draw()}catch(err){console.error('Hero preview',err)}}
async function init(){initLanguage();installListeners();showPage('home');setupHero();try{await db()}catch(err){toast(trans('المتصفح يمنع حفظ المشاريع محليًا.','This browser blocks local project storage.'),true)}}
/* Start after every deferred script (customize.js) has loaded, so its overrides are in place. */
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else setTimeout(init);
